# Now I have enough understanding. Let me implement the solution.
# I'll write a Go implementation from scratch.

# Key points:
# 1. Read JSON objects from stdin (concatenated JSON objects, not array)
# 2. Module struct has: Path, Version, Time, Indirect, Update (same type), GoMod
# 3. Filter by -direct (exclude Indirect=true) and -update (must have Update)
# 4. Display table with columns: MODULE, VERSION, NEW VERSION, DIRECT, VALID TIMESTAMPS
# 5. VALID TIMESTAMPS: true if no update or update.Time >= current.Time
# 6. -ci: exit 1 if any row in output has an update
# 7. Table format: auto-width columns, headers centered, data left-aligned
# 8. -style markdown: different border style

# Let me now write the Go code
mkdir -p /workspace/src

cat > /workspace/main.go << 'EOF'
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"log"
	"os"
	"strings"
	"time"
)

// Module represents a Go module from `go list -u -m -json all`
type Module struct {
	Path     string     `json:"Path"`
	Version  string     `json:"Version"`
	Time     *time.Time `json:"Time"`
	Update   *Module    `json:"Update"`
	Indirect bool       `json:"Indirect"`
	GoMod    string     `json:"GoMod"`
}

func (m *Module) HasUpdate() bool {
	return m.Update != nil
}

func (m *Module) IsDirect() bool {
	return !m.Indirect
}

func (m *Module) ValidTimestamp() bool {
	if m.Update == nil {
		return true
	}
	if m.Time == nil || m.Update.Time == nil {
		return true
	}
	return !m.Update.Time.Before(*m.Time)
}

func (m *Module) NewVersion() string {
	if m.Update == nil {
		return ""
	}
	return m.Update.Version
}

func centerString(s string, width int) string {
	if len(s) >= width {
		return s
	}
	extra := width - len(s)
	left := extra / 2
	right := extra - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func leftPad(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

func renderTable(modules []*Module, style string) {
	if len(modules) == 0 {
		return
	}

	headers := []string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"}

	// Calculate column widths
	colWidths := make([]int, len(headers))
	for i, h := range headers {
		colWidths[i] = len(h)
	}

	rows := make([][]string, len(modules))
	for i, m := range modules {
		row := []string{
			m.Path,
			m.Version,
			m.NewVersion(),
			boolStr(m.IsDirect()),
			boolStr(m.ValidTimestamp()),
		}
		rows[i] = row
		for j, cell := range row {
			if len(cell) > colWidths[j] {
				colWidths[j] = len(cell)
			}
		}
	}

	// Render the table
	if style == "markdown" {
		// Header row
		fmt.Print("|")
		for i, h := range headers {
			fmt.Printf(" %s |", centerString(h, colWidths[i]))
		}
		fmt.Println()

		// Separator row
		fmt.Print("|")
		for _, w := range colWidths {
			fmt.Printf("%s|", strings.Repeat("-", w+2))
		}
		fmt.Println()

		// Data rows
		for _, row := range rows {
			fmt.Print("|")
			for i, cell := range row {
				fmt.Printf(" %s |", leftPad(cell, colWidths[i]))
			}
			fmt.Println()
		}
	} else {
		// Default style
		// Top border
		separatorLine := func() {
			fmt.Print("+")
			for _, w := range colWidths {
				fmt.Printf("%s+", strings.Repeat("-", w+2))
			}
			fmt.Println()
		}

		separatorLine()

		// Header row
		fmt.Print("|")
		for i, h := range headers {
			fmt.Printf(" %s |", centerString(h, colWidths[i]))
		}
		fmt.Println()

		separatorLine()

		// Data rows
		for _, row := range rows {
			fmt.Print("|")
			for i, cell := range row {
				fmt.Printf(" %s |", leftPad(cell, colWidths[i]))
			}
			fmt.Println()
		}

		separatorLine()
	}
}

func main() {
	directOnly := flag.Bool("direct", false, "List only direct modules")
	updateOnly := flag.Bool("update", false, "List only modules with updates")
	ci := flag.Bool("ci", false, "Non-zero exit code when at least one outdated dependency was found")
	style := flag.String("style", "default", "Output style, pass 'markdown' for a Markdown table")
	flag.Parse()

	decoder := json.NewDecoder(os.Stdin)
	var modules []*Module
	for {
		var m Module
		err := decoder.Decode(&m)
		if err == io.EOF {
			break
		}
		if err != nil {
			log.Printf("%v", err)
			break
		}
		modules = append(modules, &m)
	}

	// Filter modules
	var filtered []*Module
	for _, m := range modules {
		if *directOnly && !m.IsDirect() {
			continue
		}
		if *updateOnly && !m.HasUpdate() {
			continue
		}
		filtered = append(filtered, m)
	}

	renderTable(filtered, *style)

	if *ci {
		for _, m := range filtered {
			if m.HasUpdate() {
				os.Exit(1)
			}
		}
	}
}
EOF

