# Let me update the code to replicate the exact behavior:
cat > /workspace/main.go << 'EOF'
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"log"
	"os"
	"strings"
	"time"
)

// Module represents a Go module from `go list -u -m -json all`
type Module struct {
	Path     string     `json:"Path"`
	Version  string     `json:"Version"`
	Time     *time.Time `json:"Time"`
	Update   *Module    `json:"Update"`
	Indirect bool       `json:"Indirect"`
	GoMod    string     `json:"GoMod"`
}

func (m *Module) HasUpdate() bool {
	return m.Update != nil
}

func (m *Module) IsDirect() bool {
	return !m.Indirect
}

// InvalidTimestamp returns true if the update timestamp is invalid (older than current)
// This replicates the original behavior including the nil pointer dereference bug
func (m *Module) InvalidTimestamp() bool {
	if m.Update == nil {
		return false
	}
	// This will panic if m.Update.Time is nil but m.Time is set (replicating original bug)
	return m.Update.Time.Before(*m.Time)
}

func (m *Module) NewVersion() string {
	if m.Update == nil {
		return ""
	}
	return m.Update.Version
}

func centerString(s string, width int) string {
	if len(s) >= width {
		return s
	}
	extra := width - len(s)
	left := extra / 2
	right := extra - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func leftPad(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

func renderTable(modules []*Module, style string) {
	if len(modules) == 0 {
		return
	}

	headers := []string{"MODULE", "VERSION", "NEW VERSION", "DIRECT", "VALID TIMESTAMPS"}

	// Calculate column widths
	colWidths := make([]int, len(headers))
	for i, h := range headers {
		colWidths[i] = len(h)
	}

	rows := make([][]string, len(modules))
	for i, m := range modules {
		validTS := boolStr(!m.InvalidTimestamp())
		row := []string{
			m.Path,
			m.Version,
			m.NewVersion(),
			boolStr(m.IsDirect()),
			validTS,
		}
		rows[i] = row
		for j, cell := range row {
			if len(cell) > colWidths[j] {
				colWidths[j] = len(cell)
			}
		}
	}

	// Render the table
	if style == "markdown" {
		// Header row
		fmt.Print("|")
		for i, h := range headers {
			fmt.Printf(" %s |", centerString(h, colWidths[i]))
		}
		fmt.Println()

		// Separator row
		fmt.Print("|")
		for _, w := range colWidths {
			fmt.Printf("%s|", strings.Repeat("-", w+2))
		}
		fmt.Println()

		// Data rows
		for _, row := range rows {
			fmt.Print("|")
			for i, cell := range row {
				fmt.Printf(" %s |", leftPad(cell, colWidths[i]))
			}
			fmt.Println()
		}
	} else {
		// Default style
		separatorLine := func() {
			fmt.Print("+")
			for _, w := range colWidths {
				fmt.Printf("%s+", strings.Repeat("-", w+2))
			}
			fmt.Println()
		}

		separatorLine()

		// Header row
		fmt.Print("|")
		for i, h := range headers {
			fmt.Printf(" %s |", centerString(h, colWidths[i]))
		}
		fmt.Println()

		separatorLine()

		// Data rows
		for _, row := range rows {
			fmt.Print("|")
			for i, cell := range row {
				fmt.Printf(" %s |", leftPad(cell, colWidths[i]))
			}
			fmt.Println()
		}

		separatorLine()
	}
}

func main() {
	directOnly := flag.Bool("direct", false, "List only direct modules")
	updateOnly := flag.Bool("update", false, "List only modules with updates")
	ci := flag.Bool("ci", false, "Non-zero exit code when at least one outdated dependency was found")
	style := flag.String("style", "default", "Output style, pass 'markdown' for a Markdown table")
	flag.Parse()

	decoder := json.NewDecoder(os.Stdin)
	var modules []*Module
	for {
		var m Module
		err := decoder.Decode(&m)
		if err == io.EOF {
			break
		}
		if err != nil {
			log.Printf("%v", err)
			break
		}
		modules = append(modules, &m)
	}

	// Filter modules
	var filtered []*Module
	for _, m := range modules {
		if *directOnly && !m.IsDirect() {
			continue
		}
		if *updateOnly && !m.HasUpdate() {
			continue
		}
		filtered = append(filtered, m)
	}

	renderTable(filtered, *style)

	if *ci {
		for _, m := range filtered {
			if m.HasUpdate() {
				os.Exit(1)
			}
		}
	}
}
EOF

